// Browser Revision 5 advisor (apps/web/src/features/advisor/model.mjs) against the Python
// reference (tools/economy/advisor_eco/advisor_model_v5.py) for all 3,080 plans.
// Expectations: tests/advisor/fixtures/v5-plans.json.gz, regenerated by
// python tools/economy/advisor_eco/build_advisor_parity_fixture.py.
// Data: the committed advisor DB + data/golden/advisor_cell_metrics.json.gz, shaped exactly like
// the published /api/advisor-matchups/<civ> rows (checked against the fixture's row digest).
import test from 'node:test';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {readFileSync} from 'node:fs';
import {gunzipSync} from 'node:zlib';
import {DatabaseSync} from 'node:sqlite';
import {invertMatchup, plan, CONFIG} from '../../apps/web/src/features/advisor/model.mjs';

const root = new URL('../../', import.meta.url);
const read = path => readFileSync(new URL(path, root));
const fixture = JSON.parse(gunzipSync(read('tests/advisor/fixtures/v5-plans.json.gz')));
const metricsBytes = read('data/golden/advisor_cell_metrics.json.gz');
const metrics = JSON.parse(gunzipSync(metricsBytes));
const sha = bytes => createHash('sha256').update(bytes).digest('hex');

const db = new DatabaseSync(new URL('data/golden/civ_matchups_first_pass.db', root).pathname, {readOnly: true});
const units = new Map(db.prepare('SELECT data FROM units ORDER BY id').all().map(row => {
    const unit = JSON.parse(row.data);
    return [unit.id, unit];
}));
const cells = db.prepare('SELECT * FROM cells ORDER BY a, b').all();
db.close();
const byCell = new Map(metrics.cells.map(row => [`${row[0]}:${row[1]}`, row[2]]));

/** Same as cell_value() in apps/backend/aoe2_api/services/advisor.py (value from the cell's a side). */
function cellValue(cell) {
    if (['equivalent', 'close_uncertain'].includes(cell.outcome) || cell.evidence_type === 'identity') return 0;
    const found = byCell.get(`${cell.a}:${cell.b}`);
    if (found === undefined || cell.evidence_type !== 'observed') throw new Error(`stale metrics for ${cell.a}/${cell.b}`);
    return found;
}

/** Rows of /api/advisor-matchups/<own> for opponent <enemy>, in the API's order (cells ORDER BY a, b). */
const pairRows = new Map();
for (const cell of cells) {
    const civA = units.get(cell.a).civilization, civB = units.get(cell.b).civilization;
    if (civA === civB) continue;
    const base = [cell.a, cell.b, cell.outcome, cell.evidence_type, cell.count_a, cell.count_b, cell.tier, cell.flags,
        cell.evidence_id, cellValue(cell)];
    for (const [own, enemy, row] of [[civA, civB, base], [civB, civA, invertMatchup(base)]]) {
        const key = `${own}|${enemy}`;
        if (!pairRows.has(key)) pairRows.set(key, []);
        pairRows.get(key).push(row);
    }
}

const digits = fixture.header.digits;
const round = x => x === null ? null : Number(x.toFixed(digits));
const byId = map => Object.fromEntries([...map].sort((a, b) => a[0] - b[0]).map(([k, v]) => [String(k), round(v)]));
function summary(p) {
    return {main: p.main.unit.id, support: p.support ? p.support.unit.id : null, supportGain: round(p.supportGain),
        gaps: p.gaps, additions: p.additions.map(a => [a.entry.unit.id, a.covers]), unanswered: p.unanswered,
        score: byId(p.score), multiplier: byId(p.multiplier)};
}

test('the fixture was generated from the committed data and the same settings', () => {
    assert.equal(fixture.header.cellMetricsSha256, sha(metricsBytes),
        'stale fixture: run python tools/economy/advisor_eco/build_advisor_parity_fixture.py');
    assert.equal(fixture.header.advisorDatasetSha256, metrics.advisorDataset.sha256);
    assert.equal(fixture.header.plans, 3080);
    assert.deepEqual(fixture.header.config, {...CONFIG, excludedMain: [...CONFIG.excludedMain], supportExtra: [...CONFIG.supportExtra]});
});

test('rows assembled here are the rows the API serves', () => {
    // Same text as row_digest() in build_advisor_parity_fixture.py.
    const hash = createHash('sha256');
    for (const key of [...pairRows.keys()].sort()) hash.update(`${key}\n${JSON.stringify(pairRows.get(key))}\n`);
    assert.equal(hash.digest('hex'), fixture.header.rowsSha256);
});

test('every one of the 3,080 plans equals the Python reference', () => {
    const failures = [];
    for (const {civ, enemy, ...want} of fixture.plans) {
        try { assert.deepEqual(summary(plan(pairRows.get(`${civ}|${enemy}`), units)), want); }
        catch (error) { failures.push(`${civ} vs ${enemy}: ${error.message.slice(0, 400)}`); }
    }
    assert.equal(fixture.plans.length, 3080);
    assert.deepEqual(failures.slice(0, 5), [], `${failures.length} plans differ`);
});
